// Writes src/lib/genetic-code.ts from Biopython's codon tables, so the genetic
// code lives in one generated file instead of being typed out in each module
// that needs it. Rendering runs on the main thread and cannot wait for the
// interpreter, which is why the table is baked in rather than fetched.
// Run with `npm run gen:genetic-code`; a test checks the file is still current.
import { writeFile } from 'node:fs/promises';
import { loadPyodide } from 'pyodide';

const py = await loadPyodide();
await py.loadPackage(['biopython']);
const table = py.runPython(`
from Bio.Data import CodonTable
import json
chosen = CodonTable.unambiguous_dna_by_id[1]
code = dict(chosen.forward_table)
for stop in chosen.stop_codons:
    code[stop] = "*"
json.dumps({"code": dict(sorted(code.items())), "version": __import__("Bio").__version__})
`);
const { code, version } = JSON.parse(table);

const entries = Object.entries(code);
const rows = [];
for (let index = 0; index < entries.length; index += 4) {
  rows.push(
    '  ' +
      entries
        .slice(index, index + 4)
        .map(([codon, residue]) => `${codon}: '${residue}',`)
        .join(' '),
  );
}

await writeFile(
  'src/lib/genetic-code.ts',
  [
    '// GATC - Gene Assembly & Toolkit for Cloning',
    '// Copyright (C) 2026 Xu Zhonghe',
    '// SPDX-License-Identifier: GPL-3.0-or-later',
    `// Generated by scripts/gen-genetic-code.mjs from Biopython ${version}`,
    '// (Bio.Data.CodonTable, the standard code, table 1). Do not edit by hand.',
    '//',
    '// It is baked in rather than read from the interpreter because the sequence',
    '// and map views translate while they draw, on a thread where the interpreter',
    '// does not run. genetic-code.test.ts checks it still matches Biopython.',
    '',
    `export const GENETIC_CODE: Readonly<Record<string, string>> = {`,
    ...rows,
    '};',
    '',
    '/** The residue a codon codes for; anything unreadable is X. */',
    'export function translateCodon(codon: string): string {',
    "  return GENETIC_CODE[codon.toUpperCase()] ?? 'X';",
    '}',
    '',
    '/** The other codons for the residue a codon codes for, itself included. */',
    'export const SYNONYMOUS_CODONS: Readonly<Record<string, string[]>> = (() => {',
    '  const byResidue: Record<string, string[]> = {};',
    '  for (const [codon, residue] of Object.entries(GENETIC_CODE)) {',
    '    (byResidue[residue] ??= []).push(codon);',
    '  }',
    '  return byResidue;',
    '})();',
    '',
  ].join('\n'),
);
console.log(`src/lib/genetic-code.ts: ${entries.length} codons from Biopython ${version}`);
